css:
.tariff-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #0d1733 0%, #142149 50%, #0d1733 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    color: #e8eef9;
}

.tariff-sim-container h1,
.tariff-sim-container h3 {
    margin: 0;
    color: #fff;
    letter-spacing: 0.01em;
}

.tariff-sim-header {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 24px;
    background: linear-gradient(135deg, rgba(20,33,73,0.85), rgba(13,23,51,0.85));
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 16px;
    padding: 24px 28px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(0,0,0,0.35);
}
.tariff-sim-header-flag {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 1rem;
    letter-spacing: 0.04em;
    color: #fff;
    box-shadow: 0 6px 16px rgba(0,0,0,0.3);
}
.tariff-sim-header-flag-cr {
    background: linear-gradient(135deg, #f59e0b, #ea580c);
}
.tariff-sim-header-flag-bv {
    background: linear-gradient(135deg, #38bdf8, #2563eb);
}
.tariff-sim-header-content {
    text-align: center;
}
.tariff-sim-header-eyebrow {
    color: #c4b5fd;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    margin-bottom: 6px;
}
.tariff-sim-header h1 {
    font-size: 1.75rem;
    font-weight: 700;
}
.tariff-sim-header-sub {
    color: #cfd6e6;
    font-size: 0.92rem;
    margin-top: 6px;
}

.tariff-sim-meta {
    display: grid;
    grid-template-columns: auto 1fr;
    align-items: center;
    gap: 20px;
    margin-bottom: 20px;
}
.tariff-sim-period-counter {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 12px;
    padding: 10px 18px;
    font-weight: 600;
    color: #fde68a;
    font-size: 0.95rem;
    letter-spacing: 0.04em;
}
.tariff-sim-period-counter span:nth-child(2),
.tariff-sim-period-counter span:nth-child(4) {
    color: #fff;
    font-weight: 800;
}
.tariff-sim-tariff-state {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    justify-content: flex-end;
}
.tariff-sim-tariff-pill {
    display: flex;
    flex-direction: column;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.14);
    border-radius: 10px;
    padding: 8px 16px;
    min-width: 220px;
}
.tariff-sim-tariff-pill-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #c2cae0;
}
.tariff-sim-tariff-pill-value {
    font-size: 1.4rem;
    font-weight: 800;
}
.tariff-sim-tariff-pill-bv {
    border-left: 4px solid #38bdf8;
}
.tariff-sim-tariff-pill-bv .tariff-sim-tariff-pill-value {
    color: #7dd3fc;
}
.tariff-sim-tariff-pill-cr {
    border-left: 4px solid #f59e0b;
}
.tariff-sim-tariff-pill-cr .tariff-sim-tariff-pill-value {
    color: #fbbf24;
}

.tariff-sim-briefing {
    background: linear-gradient(135deg, rgba(124,58,237,0.18), rgba(37,99,235,0.18));
    border: 1px solid rgba(196,181,253,0.35);
    border-radius: 14px;
    padding: 22px 26px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.25);
}
.tariff-sim-briefing-eyebrow {
    color: #c4b5fd;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    margin-bottom: 10px;
    font-weight: 700;
}
.tariff-sim-briefing-text {
    color: #f0f4ff;
    font-size: 0.98rem;
    line-height: 1.55;
}

.tariff-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.tariff-sim-kpi-card {
    position: relative;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 14px;
    padding: 20px 18px 18px;
    transition: transform 0.2s ease, background 0.2s ease;
    overflow: hidden;
}
.tariff-sim-kpi-card:hover {
    transform: translateY(-3px);
    background: rgba(255,255,255,0.09);
}
.tariff-sim-kpi-card::before {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
}
.tariff-sim-kpi-card-treasury::before { background: linear-gradient(90deg, #fbbf24, #f59e0b); }
.tariff-sim-kpi-card-mango::before    { background: linear-gradient(90deg, #fb923c, #ea580c); }
.tariff-sim-kpi-card-trust::before    { background: linear-gradient(90deg, #c4b5fd, #8b5cf6); }
.tariff-sim-kpi-card-trade::before    { background: linear-gradient(90deg, #34d399, #059669); }
.tariff-sim-kpi-card-political::before{ background: linear-gradient(90deg, #f472b6, #db2777); }
.tariff-sim-kpi-card-third::before    { background: linear-gradient(90deg, #38bdf8, #2563eb); }

.tariff-sim-kpi-icon {
    display: inline-block;
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    background: rgba(255,255,255,0.1);
    color: #fff;
    padding: 3px 8px;
    border-radius: 6px;
    margin-bottom: 8px;
}
.tariff-sim-kpi-label {
    color: #c2cae0;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 8px;
    line-height: 1.3;
}
.tariff-sim-kpi-value {
    font-size: 1.85rem;
    font-weight: 800;
    color: #fff;
    line-height: 1.1;
    margin-bottom: 6px;
}
.tariff-sim-kpi-card-treasury .tariff-sim-kpi-value { color: #fde68a; }
.tariff-sim-kpi-card-mango    .tariff-sim-kpi-value { color: #fb923c; }
.tariff-sim-kpi-card-trust    .tariff-sim-kpi-value { color: #c4b5fd; }
.tariff-sim-kpi-card-trade    .tariff-sim-kpi-value { color: #34d399; }
.tariff-sim-kpi-card-political .tariff-sim-kpi-value { color: #f472b6; }
.tariff-sim-kpi-card-third    .tariff-sim-kpi-value { color: #7dd3fc; }
.tariff-sim-kpi-sub {
    color: #97a3bd;
    font-size: 0.72rem;
    line-height: 1.35;
}

.tariff-sim-controls {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 16px;
    padding: 24px 26px;
    margin-bottom: 24px;
}
.tariff-sim-controls h3 {
    font-size: 1.05rem;
    margin-bottom: 18px;
    color: #fde68a;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}
.tariff-sim-control-row {
    margin-bottom: 18px;
}
.tariff-sim-control-label {
    display: block;
    font-weight: 600;
    color: #e8eef9;
    margin-bottom: 8px;
    font-size: 0.92rem;
}
.tariff-sim-control-hint {
    color: #97a3bd;
    font-size: 0.78rem;
    margin-top: 6px;
    line-height: 1.45;
}

.tariff-sim-select,
.tariff-sim-controls input[type="number"],
.tariff-sim-controls input[type="text"] {
    width: 100%;
    background: #0d1733;
    border: 1px solid #334475;
    color: #e8eef9;
    border-radius: 8px;
    padding: 10px 14px;
    font-size: 0.95rem;
    font-family: inherit;
}
.tariff-sim-select:focus,
.tariff-sim-controls input:focus {
    outline: none;
    border-color: #fbbf24;
    box-shadow: 0 0 0 3px rgba(251,191,36,0.18);
}
.tariff-sim-select option {
    background: #0d1733;
    color: #e8eef9;
}

.tariff-sim-buttons {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    margin-top: 8px;
}
.tariff-sim-submit-btn {
    background: linear-gradient(135deg, #f59e0b, #ea580c);
    border: none;
    color: #0d1733;
    font-weight: 700;
    padding: 12px 22px;
    border-radius: 10px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-size: 0.85rem;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.tariff-sim-submit-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 8px 20px rgba(245,158,11,0.4);
    color: #0d1733;
}
.tariff-sim-undo-btn {
    background: transparent;
    border: 1px solid rgba(255,255,255,0.25);
    color: #cfd6e6;
    border-radius: 10px;
    padding: 10px 18px;
}
.tariff-sim-undo-btn:hover {
    background: rgba(255,255,255,0.08);
    color: #fff;
    border-color: rgba(255,255,255,0.4);
}

.tariff-sim-history {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 20px 22px 22px;
    margin-bottom: 24px;
}
.tariff-sim-history h3 {
    font-size: 1rem;
    margin-bottom: 14px;
    color: #fde68a;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}
.tariff-sim-history-table-wrap {
    overflow-x: auto;
}
.tariff-sim-history table {
    width: 100%;
    color: #e8eef9;
    margin-bottom: 0;
}
.tariff-sim-history table thead th {
    color: #c2cae0;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-bottom: 1px solid rgba(255,255,255,0.12);
    padding: 8px 10px;
    background: transparent;
}
.tariff-sim-history table tbody td {
    color: #e8eef9;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    padding: 8px 10px;
    font-size: 0.88rem;
}
.tariff-sim-history table tbody tr:hover {
    background: rgba(255,255,255,0.04);
}

.tariff-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}
.tariff-sim-chart-card {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 18px 20px;
}
.tariff-sim-chart-card h3 {
    font-size: 0.92rem;
    margin-bottom: 10px;
    color: #cfd6e6;
    letter-spacing: 0.04em;
}
.tariff-sim-chart-canvas-wrap {
    position: relative;
    height: 240px;
}
.tariff-sim-chart-card:nth-child(3) {
    grid-column: 1 / -1;
}

@media (max-width: 768px) {
    .tariff-sim-container { padding: 16px; }
    .tariff-sim-header {
        grid-template-columns: 1fr;
        text-align: center;
        padding: 18px;
    }
    .tariff-sim-header-flag { margin: 0 auto; }
    .tariff-sim-meta { grid-template-columns: 1fr; }
    .tariff-sim-tariff-state { justify-content: stretch; }
    .tariff-sim-tariff-pill { min-width: 0; flex: 1 1 45%; }
    .tariff-sim-charts { grid-template-columns: 1fr; }
    .tariff-sim-chart-card:nth-child(3) { grid-column: 1; }
    .tariff-sim-kpi-value { font-size: 1.5rem; }
}


/* --- EQIL 2026-08-07: focus, motion, completion panel --- */
.tariff-sim-container :focus-visible,
.tariff-sim-container select:focus-visible,
.tariff-sim-container button:focus-visible {
    outline: 3px solid #f0b429;
    outline-offset: 2px;
    border-radius: 3px;
}
.tariff-sim-actions { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.tariff-sim-completion {
    background: #14203a;
    border: 1px solid #2d3f55;
    border-left: 5px solid #f0b429;
    border-radius: 6px;
    padding: 22px 26px;
    margin: 20px 0;
    color: #e6ecf5;
}
.tariff-sim-debrief h3 { margin: 0 0 10px; font-size: 1.12rem; color: #ffffff; }
.tariff-sim-debrief-headline { font-size: 1rem; margin-bottom: 14px; }
.tariff-sim-debrief-list {
    list-style: none; padding: 0; margin: 0 0 14px;
    display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 8px;
}
.tariff-sim-debrief-list li {
    display: flex; justify-content: space-between; gap: 12px;
    background: #0d1730; border: 1px solid #2d3f55; border-radius: 4px; padding: 8px 12px;
}
.tariff-sim-debrief-k { color: #9fb0c6; font-size: 0.8rem; }
.tariff-sim-debrief-v { font-weight: 700; color: #ffffff; }
.tariff-sim-debrief-insights p { margin: 0 0 8px; font-size: 0.9rem; line-height: 1.5; color: #c9d5e4; }
@media (prefers-reduced-motion: reduce) {
    .tariff-sim-container *,
    .tariff-sim-container *::before,
    .tariff-sim-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

