        getHint(state, results) {
            if (!results) return null;
            if (results.action === 'hold' && results.costarianTariff === 25 && state.currentPeriod === 1) {
                return window.mySimulation.t('hint_round1_proportional');
            }
            if (results.costarianTariff >= 50) {
                return window.mySimulation.t('hint_escalation_laffer');
            }
            if (results.action === 'wto' && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_wto_slow');
            }
            if (results.action === 'subsidize') {
                return window.mySimulation.t('hint_subsidy_treasury');
            }
            if (results.action === 'negotiate' && state.domainState.negotiationStreak >= 2) {
                return window.mySimulation.t('hint_negotiate_progress');
            }
            if (results.thirdCountry >= 15) {
                return window.mySimulation.t('hint_third_country');
            }
            if (results.netWelfareQuarter < -20) {
                return window.mySimulation.t('hint_negative_welfare');
            }
            return null;
        }

