        getPerformanceSummary(history) {
            if (!history.length) return {};

            const last = history[history.length - 1];
            const ds = last.domainState || {};

            const totalWelfare = Math.round(ds.cumulativeWelfareCR || 0);
            const finalTrust = Math.round(ds.trustIndex || 0);
            const finalTrade = Math.round(ds.bilateralTrade || 0);
            const finalEmployment = Math.round(ds.mangoEmployment || 0);
            const finalPolitical = Math.round(ds.politicalCapital || 0);
            const thirdCountry = Math.round(ds.thirdCountryShare || 0);

            let performance = 'beginner';
            let overall = 0;
            const insights = [];

            // Composite anchored on this sim own band thresholds, so the number and the
            // label can never disagree; within a band it tracks the welfare outcome.
            const span = function(v, lo, hi, outLo, outHi) {
                if (hi === lo) return outHi;
                const f = Math.max(0, Math.min(1, (v - lo) / (hi - lo)));
                return outLo + f * (outHi - outLo);
            };
            if (totalWelfare >= -50 && finalTrust >= 70 && finalTrade >= 80) {
                performance = 'excellent';
                overall = span(totalWelfare, -50, 0, 80, 100);
                insights.push(this._t('insight_offramp'));
            } else if (totalWelfare >= -150 && finalTrust >= 55) {
                performance = 'good';
                overall = span(totalWelfare, -150, -50, 60, 79);
                insights.push(this._t('insight_solid'));
            } else if (totalWelfare >= -300) {
                performance = 'fair';
                overall = span(totalWelfare, -300, -150, 40, 59);
                insights.push(this._t('insight_workable'));
            } else {
                performance = 'beginner';
                overall = span(totalWelfare, -600, -300, 0, 39);
                insights.push(this._t('insight_optics'));
            }
            const perfKey = 'perf_' + performance;
            overall = Math.max(0, Math.min(100, Math.round(overall)));

            if (finalEmployment < 130000) insights.push(this._t('insight_employment'));
            if (thirdCountry >= 20) insights.push(this._t('insight_thirdcountry'));
            if (finalTrust < 60) insights.push(this._t('insight_trust'));
            if (finalPolitical < 60) insights.push(this._t('insight_political'));
            insights.push(this._t('insight_honest'));

            return {
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                totalWelfare,
                finalTrust,
                finalTrade,
                finalEmployment,
                finalPolitical,
                thirdCountry,
                performance,
                performanceKey: perfKey,
                performanceLabel: this._t(perfKey),
                insights
            };
        }

        _t(key) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                const v = window.mySimulation.t(key);
                if (v) return v;
            }
            return key;
        }

        _isRunComplete(period) {
            const st = (window.mySimulation && window.mySimulation.state) || {};
            const maxP = parseInt(st.maxPeriods, 10) || 6;
            const hist = Array.isArray(st.history) ? st.history : [];
            if (hist.length >= maxP) return true;
            return (period || 1) > maxP;
        }

        _syncControlsFromDecisions(state) {
            const dec = (state && state.decisions) || {};
            const tEl = document.getElementById('tariffInput');
            if (tEl && dec.costarianTariff !== undefined && dec.costarianTariff !== null) {
                tEl.value = String(dec.costarianTariff);
            }
            const aEl = document.getElementById('actionInput');
            if (aEl && dec.action) aEl.value = dec.action;
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = this._t.bind(this);
            const esc = function(v) {
                return String(v === undefined || v === null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            const rows = [
                [t('debrief_welfare'), '$' + esc(s.totalWelfare) + 'm'],
                [t('debrief_trust'), esc(s.finalTrust)],
                [t('debrief_trade'), esc(s.finalTrade) + '%'],
                [t('debrief_jobs'), Math.round(s.finalEmployment || 0).toLocaleString()],
                [t('debrief_third'), esc(s.thirdCountry) + '%']
            ].map(function(r) {
                return '<li><span class="tariff-sim-debrief-k">' + esc(r[0]) + '</span>' +
                       '<span class="tariff-sim-debrief-v">' + esc(r[1]) + '</span></li>';
            }).join('');
            const ins = (s.insights || []).map(function(x) { return '<p>' + esc(x) + '</p>'; }).join('');
            return '<div class="tariff-sim-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="tariff-sim-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<ul class="tariff-sim-debrief-list">' + rows + '</ul>' +
                     '<div class="tariff-sim-debrief-insights">' + ins + '</div>' +
                   '</div>';
        }

        _updateBriefing(state) {
            const period = (state && state.currentPeriod) || 1;
            const over = this._isRunComplete(period);
            const actions = document.querySelector('.tariff-sim-actions');
            if (actions) actions.style.display = over ? 'none' : 'flex';
            const controls = document.getElementById('decisionPanel');
            if (controls) controls.style.display = over ? 'none' : 'block';
            const done = document.getElementById('completionPanel');
            if (done) {
                done.style.display = over ? 'block' : 'none';
                if (over && !done.innerHTML) {
                    done.innerHTML = (window.mySimulation && window.mySimulation.lastCompletionHTML) ||
                        ('<div class="tariff-sim-debrief"><h3>' + this._t('debrief_heading') + '</h3></div>');
                }
            }
            const idx = Math.min(period - 1, 5);
            const ds = state.domainState || {};
            const t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            const briefings = [
                t('brief_q1'),
                t('brief_q2'),
                t('brief_q3'),
                t('brief_q4'),
                t('brief_q5'),
                t('brief_q6')
            ];

            let extra = '';
            if (ds.wtoStatus === 'filed') extra = '<br><br>' + t('wto_filed_note');
            if (ds.wtoStatus === 'panel') extra = '<br><br>' + t('wto_panel_note');
            if (ds.wtoStatus === 'ruling-mixed') extra = '<br><br>' + t('wto_ruling_note');
            if (ds.boravianTariff >= 50) extra += '<br><br>' + t('boravia_escalated_note');
            if (ds.thirdCountryShare >= 15) extra += '<br><br>' + t('third_country_note');

            const el = document.getElementById('briefingText');
            if (el) el.innerHTML = (briefings[idx] || '') + extra;
        }

